CREATE TABLE trg17_stock (item_id INTEGER PRIMARY KEY, item_name TEXT NOT NULL, quantity INTEGER NOT NULL);
CREATE TRIGGER trg17_stock_nonnegative BEFORE INSERT ON trg17_stock WHEN NEW.quantity < 0 BEGIN SELECT RAISE(ABORT, 'quantity must be non-negative'); END;
INSERT INTO trg17_stock VALUES (1, 'Cable', 5);
SELECT item_name, quantity FROM trg17_stock;

